    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        scanner.nextLine(); // 消耗换行符
        Queue<int[]> pq = new LinkedList<>();
        Map<Integer, Integer> status = new HashMap<>();

        // 初始化状态
        for (int i = 0; i < n; i++) {
            status.put(i, 1);
        }
​
        // 读取依赖关系
        while (scanner.hasNextLine()) {
            String s = scanner.nextLine();
            List<String> tmp = split(s, " ");
            int last = Integer.parseInt(tmp.get(0));
            int next = Integer.parseInt(tmp.get(1));
            pq.add(new int[]{last, next});
            status.put(next, 0); // 标记依赖项为未开启
        }
​
        // 处理依赖关系
        while (!pq.isEmpty()) {
            Queue<int[]> tmp = new LinkedList<>();
            boolean flag = false;
            while (!pq.isEmpty()) {
                int[] p = pq.poll();
                int last = p[0];
                int next = p[1];
                if (status.get(last) == 1) { // 如果前一个格子开启
                    if (status.get(next) == 0) {
                        flag = true;
                    }
                    status.put(next, 1); // 标记当前格子为开启
                } else {
                    tmp.add(p);
                }
            }
            pq = tmp;
            if (!flag) {
                break;
            }
        }
​
        // 判断结果
        boolean res = true;
        for (Map.Entry<Integer, Integer> entry : status.entrySet()) {
            if (entry.getValue() == 0) {
                res = false;
                System.out.println(entry.getKey());
                break;
            }
        }
​
        System.out.println(res ? "yes" : "no");
        scanner.close();
    }
