const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
function main() {
    rl.question('', (n) => {
        n = parseInt(n);
        let pq = [];
        let status = {};
        for (let i = 0; i < n; i++) {
            status[i] = 1;
        }
​
        // 读取依赖关系
        rl.on('line', (s) => {
            if (s.trim() === '') {
                // 输入结束
                rl.close();
                return;
            }
​
            let tmp = split(s, " ");
            let last = parseInt(tmp[0]);
            let next = parseInt(tmp[1]);
            pq.push([last, next]);
            status[next] = 0;
        });
​
        rl.on('close', () => {
            // 处理依赖关系
            while (pq.length > 0) {
                let tmp = [];
                let flag = false;
                while (pq.length > 0) {
                    let [last, next] = pq.shift();
                    if (status[last] === 1) { // 如果前一个格子开启
                        if (status[next] === 0) {
                            flag = true;
                        }
                        status[next] = 1;
                    } else {
                        tmp.push([last, next]);
                    }
                }
                pq = tmp;
                if (!flag) {
                    break;
                }
