package main
​
import (
    "fmt"
    "strings"
    "strconv"
)
​
func split(str, delimiter string) []string {
    var result []string
    start := 0
    end := strings.Index(str, delimiter)
    for end != -1 {
        result = append(result, str[start:end])
        start = end + len(delimiter)
        end = strings.Index(str[start:], delimiter)
    }
    result = append(result, str[start:])
    return result
}
​
func main() {
    var n int
    // 读取格子数量
    fmt.Scan(&n)
​
    // 记录依赖关系
    var pq [][]int
    // 记录每个格子的入度
    inDegree := make(map[int]int)
​
    // 初始化入度
    for i := 0; i < n; i++ {
        inDegree[i] = 0
    }
​
    var s string
    // 读取依赖关系
    // 使用 `Scanln` 持续读取输入，直到输入结束
    for {
        _, err := fmt.Scanln(&s)
        if err != nil {
            break
        }
​
        // 分割字符串获取依赖关系
        tmp := split(s, " ")
        if len(tmp) < 2 {
            continue // 忽略无效输入
        }
​
        last, err := strconv.Atoi(tmp[0])
        if err != nil {
            continue // 如果转换失败则跳过
        }
        next, err := strconv.Atoi(tmp[1])
        if err != nil {
            continue // 如果转换失败则跳过
        }
        // 记录依赖关系
        pq = append(pq, []int{last, next})
        inDegree[next]++ // 增加next的入度
    }
​
    // 队列，用于存储入度为0的节点（初始时可以跳的格子）
    var queue []int
    for i := 0; i < n; i++ {
        if inDegree[i] == 0 {
            queue = append(queue, i)
        }
    }
​
    // 处理依赖关系，拓扑排序
    visited := 0
    for len(queue) > 0 {
        node := queue[0]
        queue = queue[1:]
​
        // 标记已访问
        visited++
​
        // 更新与当前节点相关联的依赖格子的入度
        for _, p := range pq {
            if p[0] == node {
                inDegree[p[1]]--
                if inDegree[p[1]] == 0 {
                    queue = append(queue, p[1])
                }
            }
        }
    }
​
    // 判断是否所有格子都能跳
    if visited == n {
        fmt.Println("yes")
    } else {
        fmt.Println("no")
    }
}
